  st=pos.copy();sl=Slerp([0,1],Rotation.from_matrix([R,rt]))
  for t in range(dur):
   f=(t+1)/dur;R=sl(f).as_matrix();c.root[0]=root*min(1,s._steps/100)
   if ip==3:pos=st.copy()
   elif ip==4:pos=st+[-.3*f,0,.02*f]
