   if save and t%20==0:print(s._steps,s.data.qpos[:3].round(3),s.data.xpos[b].round(3),s.data.xpos[48].round(3),flush=True)
   if done:break
  if done:break
 h=np.array(h);mov=np.max(op[0]-h[:,3]);best=np.min(np.linalg.norm(h[:,3:6]-[.8,.05,.95],axis=1));score=mov*100-best*5-10*max(0,.85-h[-1,2]);res=score,mov,len(acts),par,h[-1,3:6]
