 with mp.Pool(12) as pool:
  best=-100
  for r in pool.imap_unordered(run,pars):
   print(r,flush=True)
   if r[0]>best:best=r[0];np.save('/app/output/clutch_params.npy',np.array(r[3],dtype=object),allow_pickle=True);run(r[3],True)
